dslRule:
/*!
<!id: java-completion-triggers.add-semicolon-to-method-triggers>
<!description: Add semicolon as a trigger character for method completion proposals with arguments.>
<!severity: HINT>
*/
char[] $field = new char[] { '(', '-', ' ' };
=>
char[] $field = new char[] { ';', '(', '-', ' ' };
:: isField($field) && matchesAny($field, "METHOD_WITH_ARGUMENTS_TRIGGERS")
;;

beforeExample:
package org.eclipse.jdt.internal.ui.text.java;

public class JavaMethodCompletionProposal {
    protected final static char[] METHOD_TRIGGERS= new char[] { ';', ',', '.', '\t', '[' };
    protected final static char[] METHOD_WITH_ARGUMENTS_TRIGGERS= new char[] { '(', '-', ' ' };
    protected final static char[] METHOD_NAME_TRIGGERS= new char[] { ';' };
}

afterExample:
package org.eclipse.jdt.internal.ui.text.java;

public class JavaMethodCompletionProposal {
    protected final static char[] METHOD_TRIGGERS= new char[] { ';', ',', '.', '\t', '[' };
    protected final static char[] METHOD_WITH_ARGUMENTS_TRIGGERS= new char[] { ';', '(', '-', ' ' };
    protected final static char[] METHOD_NAME_TRIGGERS= new char[] { ';' };
}

negativeExample:
package org.eclipse.jdt.internal.ui.text.java;

public class JavaMethodCompletionProposal {
    // Should not match: different content
    protected final static char[] METHOD_WITH_ARGUMENTS_TRIGGERS= new char[] { ';', '(', '-', ' ' }; 
    // Should not match: different field name, even if content is identical
    protected final static char[] OTHER_TRIGGERS= new char[] { '(', '-', ' ' };
}
